const L=11.5;
const hwAt=t=>{let b;if(t<0.4)b=1.75+0.4*Math.sin(t/0.4*Math.PI/2);else b=2.15*Math.pow(Math.cos((t-0.4)/0.6*Math.PI/2),0.8);return Math.max(b,0.1);};
const ydAt=t=>{const u=Math.abs(2*t-1);return 2.2+0.8*Math.pow(u,2.2);};
const ybAt=t=>0.2+1.5*Math.pow(Math.max(0,(0.3-t)/0.3),2)+0.8*Math.pow(Math.max(0,(0.3-t)/0.3),1)*0+1.6*Math.pow(Math.max(0,(t-0.5)/0.5),2);
const slopeDeg=t=>{const e=0.01;const s=(ydAt(Math.min(1,t+e))-ydAt(Math.max(0,t-e)))/((Math.min(1,t+e)-Math.max(0,t-e))*L);return -Math.atan(s)*180/Math.PI;};
const HC=params.hullColor,GC=params.trimColor;
const woodM={preset:'wood',roughness:0.45,metalness:0.05};
const goldM={preset:'gold',color:GC,metalness:0.8,roughness:0.35};
const mastM={preset:'wood',color:api.mix(HC,'#5a3a20',0.35),roughness:0.7};
const ropeM={preset:'fabric',color:'#6b5a3c',roughness:0.9};
const sailM={preset:'fabric',color:params.sailColor,roughness:0.95};
const redM={preset:'fabric',color:params.pennantColor,roughness:0.7};
const glowM={preset:'emissive',color:params.lanternColor,emissive:params.lanternColor,emissiveIntensity:2.5};
const blackM={preset:'plastic',color:'#0a0605',roughness:0.9};
const portM={preset:'plastic',color:'#8a1c14',roughness:0.6};
function mg(o,m){if(o.m)o.m.merge(m);else o.m=m;}
function fin(o,mat){if(o.m)api.add(o.m,mat);}
const N=60,step=L/N;
const hull={m:null},gold={m:null};
for(let i=0;i<N;i++){
 const t=(i+0.5)/N,zc=-L/2+t*L;
 const hw=hwAt(t),yb=ybAt(t),yd=ydAt(t),ym=yb+(yd-yb)*0.55,bw=hw*0.3;
 const s=api.extrude([[-bw,yb],[bw,yb],[hw,ym],[hw*0.93,yd+0.45],[-hw*0.93,yd+0.45],[-hw,ym]],step*1.04).translate(0,0,zc);
 s.vertexColor((x,y,z)=>api.mix(HC,'#24140a',0.4*Math.max(0,api.noise2(y*3,zc*2)+0.2)));
 mg(hull,s);
 const sl=slopeDeg(t);
 for(const sd of [-1,1]){
  mg(gold,api.box(0.15,0.14,step*1.2).rotate(sl*0.0,0,0).translate(sd*(hw+0.02),ym-0.12,zc));
  mg(gold,api.box(0.2,0.14,step*1.25).rotate(sl,0,0).translate(sd*hw*0.93,yd+0.45,zc));
 }
}
fin(hull,woodM);fin(gold,goldM);
const ports={m:null},frames={m:null};
for(let k=0;k<6;k++){const t=0.3+k*0.08,hw=hwAt(t),yb=ybAt(t),yd=ydAt(t),ym=yb+(yd-yb)*0.55,y=ym+(yd-ym)*0.4+0.05,zc=-L/2+t*L;
 for(const sd of [-1,1]){mg(ports,api.box(0.1,0.3,0.4).translate(sd*(hw*0.985+0.035),y,zc));mg(frames,api.box(0.06,0.4,0.52).translate(sd*(hw*0.985+0.015),y,zc));}}
fin(frames,portM);fin(ports,blackM);
const cast1=api.box(3.3,1.4,2.6).translate(0,3.2,-4.3);cast1.vertexColor(()=>HC);api.add(cast1,woodM);
const cast2=api.box(2.9,1.0,2.8).translate(0,4.4,-5.0);cast2.vertexColor(()=>HC);api.add(cast2,woodM);
api.add(api.box(3.5,0.14,2.6).translate(0,3.93,-4.3),goldM);
api.add(api.box(3.15,0.14,3.0).translate(0,4.95,-5.0),goldM);
for(const sd of [-1,1])for(const zz of [-6.2,-5.4])api.add(api.box(0.12,0.4,0.12).rotate(0,0,sd*30).translate(sd*1.1,3.7,zz),goldM);
const win={m:null};
for(let k=-1;k<=1;k++){mg(win,api.box(0.5,0.45,0.06).translate(k*0.9,4.4,-6.42));}
for(const sd of [-1,1])for(let k=0;k<3;k++){mg(win,api.box(0.06,0.4,0.45).translate(sd*1.47,4.4,-5.9+k*0.95));mg(win,api.box(0.06,0.4,0.45).translate(sd*1.67,3.3,-5.1+k*0.95));}
fin(win,glowM);
api.add(api.box(3.0,0.1,0.1).translate(0,4.0,-6.42),goldM);
const lz=-6.0;
api.add(api.cylinder(0.04,0.04,0.7,6).translate(0,5.35,lz),goldM);
api.add(api.sphere(0.2,2).scale(1,1.3,1).translate(0,5.85,lz),glowM);
api.add(api.cone(0.25,0.25,8).translate(0,6.22,lz),goldM);
api.add(api.cylinder(0.24,0.2,0.06,8).translate(0,5.6,lz),goldM);
const fc=api.box(1.6,1.3,1.1).translate(0,3.2,3.9);fc.vertexColor(()=>HC);api.add(fc,woodM);
const fr=api.cylinder(0.8,0.8,1.3,16).translate(0,3.2,4.45);fr.vertexColor(()=>HC);api.add(fr,woodM);
api.add(api.cylinder(0.9,0.9,0.12,16).translate(0,3.9,4.45),goldM);
api.add(api.box(1.8,0.12,1.1).translate(0,3.9,3.9),goldM);
const dirY=Math.cos(72*Math.PI/180),dirZ=Math.sin(72*Math.PI/180);
const bs=[0,3.0,4.9];
api.add(api.cylinder(0.06,0.14,3.8,8).rotate(72,0,0).translate(bs[0],bs[1]+dirY*1.9,bs[2]+dirZ*1.9),mastM);
const tip=[0,bs[1]+dirY*3.8,bs[2]+dirZ*3.8];
api.add(api.sphere(0.12,1).translate(tip[0],tip[1],tip[2]),goldM);
const masts=[{z:3.0,H:11.2,ws:4.5,n:params.sailTiers},{z:0.3,H:12.6,ws:5.3,n:params.sailTiers},{z:-2.2,H:9.6,ws:3.8,n:Math.min(2,params.sailTiers)}];
const y0=2.3;
for(const m of masts){
 api.add(api.cylinder(0.07,0.15,m.H-y0,8).translate(0,(m.H+y0)/2,m.z),mastM);
 api.add(api.sphere(0.1,1).translate(0,m.H+0.05,m.z),goldM);
 api.add(api.extrude([[0,0],[0,0.3],[1.3,0.15]],0.02).rotate(0,-90,0).translate(0,m.H+0.2,m.z+0.05),redM);
 const yTop=m.H-0.35,avail=yTop-(y0+1.6),pitch=avail/m.n,sh=pitch*0.96;
 for(let k=0;k<m.n;k++){
  const yt=yTop-k*pitch,yc=yt-sh/2,yl=m.ws*(1-0.15*k),w=yl*0.88;
  const bul=params.billow;
  const f=(x,z)=>{const u=2*x/w,v=2*z/sh;return bul*(1-u*u)*(1-v*v)*(0.6+0.3*v);};
  const g=(x,z)=>-f(x,z);
  api.add(api.heightfield(12,8,w,sh,f).rotate(90,0,0).translate(0,yc,m.z+0.22),sailM);
  api.add(api.heightfield(12,8,w,sh,g).rotate(90,0,0).translate(0,yc,m.z+0.18),sailM);
  api.add(api.cylinder(0.055,0.055,yl,6).rotate(0,0,90).translate(0,yt,m.z+0.2),mastM);
 }
 api.add(api.cylinder(0.55,0.42,0.25,10).translate(0,m.H-1.0,m.z),mastM);
}
const rope=(pts)=>api.add(api.tube(pts,0.014,4),ropeM);
for(const m of masts){
 const t=(m.z+L/2)/L,hw=hwAt(t)*0.95,yd=ydAt(t)+0.5;
 for(const sd of [-1,1])for(const dz of [-0.5,0.1,0.7]){
  rope([[sd*0.15,m.H*0.78,m.z],[sd*hw,yd,m.z+dz]]);
 }
}
rope([[0,11.2,3.0],[0,4.0,7.4]]);
rope([[0,11.2,3.0],tip]);
rope([[0,12.6,0.3],[0,11.2,3.0]]);
rope([[0,12.6,0.3],[0,9.6,-2.2]]);
rope([[0,9.6,-2.2],[0,5.0,-6.0]]);
api.add(api.extrude([[0,0],[0,0.5],[1.8,0.4],[1.5,0.25],[1.8,0.1]],0.02).rotate(0,-90,0).translate(0,12.75,0.3),redM);
api.collider({kind:'box',halfExtents:[2.1,1.8,L/2-0.5],offset:[0,1.9,0]});
api.collider({kind:'box',halfExtents:[1.6,1.2,2.2],offset:[0,3.8,-4.7]});
api.collider({kind:'box',halfExtents:[0.9,0.65,1.0],offset:[0,3.2,4.2]});
for(const m of masts)api.collider({kind:'cylinder',radius:0.15,halfHeight:(m.H-y0)/2,offset:[0,(m.H+y0)/2,m.z]});
return api.build();
